import{_ as o,a as r}from"./chunks/notes-editor.DnBZdfY-.js";import{_ as a,o as e,c as d,a2 as l}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"ノート","description":"ノートは、コマと位置合わせが存在する理由です。ノートはページ全体または1つのコマにぶら下がり、Markdown で書き、タグ、出典、添付スクリーンショットを持てます。","frontmatter":{"description":"ノートは、コマと位置合わせが存在する理由です。ノートはページ全体または1つのコマにぶら下がり、Markdown で書き、タグ、出典、添付スクリーンショットを持てます。"},"headers":[],"relativePath":"ja/guide/notes.md","filePath":"ja/guide/notes.md","lastUpdated":1794764349000}'),i={name:"ja/guide/notes.md"};function n(s,t,c,g,h,u){return e(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="ノート" tabindex="-1">ノート <a class="header-anchor" href="#ノート" aria-label="Permalink to &quot;ノート&quot;">​</a></h1><p>ノートは、コマと位置合わせが存在する理由です。ノートはページ全体または1つのコマにぶら下がり、Markdown で書き、タグ、出典、添付スクリーンショットを持てます。</p><figure class="shot"><img src="'+o+'" alt="Markdown エディター、ライブプレビュー、タグ、一覧タブを備えたノートパネル"><figcaption>ノート列はステージの右側にあり、折りたたむことができます。エディター上のツールバーは Markdown を挿入し、タブバーでこのページと全体の一覧を切り替えます。</figcaption></figure><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>「この翻訳は敬称を落としている」といった所見は、参照している吹き出しから切り離された瞬間に意味を失います。ここではノートはページまたはコマの id に紐付くため、ページの並べ替え、テンプレートの変更、エクスポートを越えて残ります。2つ目の課題は検索です。50ページを超えると、<code>語気</code> タグの付いたノートも、ある記事を出典とするノートも、すべて引っ張り出したくなります。</p><h2 id="ページノートとコマノート" tabindex="-1">ページノートとコマノート <a class="header-anchor" href="#ページノートとコマノート" aria-label="Permalink to &quot;ページノートとコマノート&quot;">​</a></h2><table tabindex="0"><thead><tr><th>範囲</th><th>使う場面</th><th>保存形式</th></tr></thead><tbody><tr><td><strong>ページ</strong></td><td>全体の所見、校正の指摘、ページについての疑問。</td><td><code>scope: &quot;page&quot;</code>、<code>panelId: null</code></td></tr><tr><td><strong>コマ</strong></td><td>言い回し、語気、特定の吹き出し、翻訳の違い。</td><td><code>scope: &quot;panel&quot;</code>、<code>panelId: &quot;&lt;panel id&gt;&quot;</code></td></tr></tbody></table><p>ワークベンチまたは比較リーダーでコマを選択すると、次のノートはそのコマに紐付きます。何も選択していない場合、ノートはページ単位になります。エディターのプレースホルダーが有効な範囲を示します。<em>このコマの原文、訳の違い、語気などを記録…</em> と <em>ページ全体の気づき、疑問、校正メモなどを記録…</em> です。</p><h2 id="ノートを書く" tabindex="-1">ノートを書く <a class="header-anchor" href="#ノートを書く" aria-label="Permalink to &quot;ノートを書く&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="ノートエディター。Markdown ツールバー、編集 / 分割 / プレビュー、出典とタグの入力欄、スクラッチパッド"><figcaption>ノートエディター。Markdown ツールバー、編集 / 分割 / プレビュー、出典とタグの欄、その下にスクラッチパッドがあります。上部の範囲表示で、次のノートがページ用かコマ用かが分かります。</figcaption></figure><ol><li><strong>このページ</strong> タブのエディターをクリックします。</li><li>Markdown を入力します。ツールバーがよく使う記法を挿入します。</li></ol><table tabindex="0"><thead><tr><th>ボタン</th><th>挿入内容</th></tr></thead><tbody><tr><td><strong>B</strong></td><td>太字（<code>Ctrl+B</code>）</td></tr><tr><td><em>I</em></td><td>斜体（<code>Ctrl+I</code>）</td></tr><tr><td>• リスト</td><td>箇条書き</td></tr><tr><td>❝ 引用</td><td>引用ブロック</td></tr><tr><td><code>&lt;/&gt;</code></td><td>インラインコード</td></tr><tr><td>↗ リンク</td><td>リンク（<code>Ctrl+K</code>）</td></tr><tr><td>H</td><td>見出し</td></tr><tr><td>S</td><td>取り消し線</td></tr><tr><td>1.</td><td>番号付きリスト</td></tr><tr><td>—</td><td>区切り線</td></tr></tbody></table><ol start="3"><li>モードを選びます。<strong>編集</strong>、<strong>分割</strong>（エディター + プレビュー）、<strong>プレビュー</strong> です。</li><li><code>Ctrl+Enter</code> を押すか、<strong>ノートを追加</strong> をクリックします。</li></ol><p>レンダリングされた出力は生の HTML をエスケープするため、HTML が実行されることはありません。Markdown 対応前に書かれたノートは、改行を保ったプレーンテキストとして表示されます。</p><h2 id="タグ" tabindex="-1">タグ <a class="header-anchor" href="#タグ" aria-label="Permalink to &quot;タグ&quot;">​</a></h2><ul><li>タグを入力して <code>Enter</code> を押すと追加されます。</li><li>タグはノート上の配列として保存されます。</li><li>使用状況はすべてのページから集計されて候補として提示され、<strong>絞り込み</strong> の行で現在のページをタグで絞り込めます。</li></ul><p>タグは、自分用の分類を作るもっとも手軽な方法です。<code>語気</code>、<code>誤訳</code>、<code>文化</code>、<code>要確認</code>、<code>オノマトペ</code> などがあります。</p><h2 id="添付画像" tabindex="-1">添付画像 <a class="header-anchor" href="#添付画像" aria-label="Permalink to &quot;添付画像&quot;">​</a></h2><p>ノートにはスクリーンショットを添付できます。参照ページ、版の比較、あるいはスキャンする気になれない紙の本の写真などに。</p><ul><li>エディターに画像を<strong>貼り付け</strong>るか、ノートのフォームへ<strong>ドラッグ＆ドロップ</strong>します。</li><li><strong>画像を追加</strong> でファイル選択を開きます。添付した画像ごとにサムネイルと削除ボタンが付きます。</li><li>400 KB 未満の画像はそのまま（data URL）保存します。それより大きい画像は長辺1600 px 以下に縮小し、品質0.85の WebP に再エンコードします。</li><li>画像はページ JSON のノートの <code>images</code> 配列に保存されるため、エクスポートやプロジェクトファイルでもページと一緒に移動します。数が非常に多いと JSON が大きくなるので、ページ全体より切り取った参照をいくつか使うことをおすすめします。</li></ul><h2 id="出典" tabindex="-1">出典 <a class="header-anchor" href="#出典" aria-label="Permalink to &quot;出典&quot;">​</a></h2><p>各ノートは出典を持てます。</p><ul><li><strong>URL</strong> — リンクを貼り付けます。ノート本文の最初の URL が自動で入力されます。<strong>タイトル取得</strong> は5秒のタイムアウトでページタイトルの読み取りを試みます。取得がブロックされる場合は、タイトルを手入力してください。</li><li><strong>自由入力</strong> — 例：<code>ChatGPT conversation 2026-05-12</code>、書籍名、インタビュー名。</li></ul><p>出典はノートの下に表示され、<strong>出典を閉じる</strong> で切り替えられます。</p><h2 id="llm-用の文脈をコピー" tabindex="-1">LLM 用の文脈をコピー <a class="header-anchor" href="#llm-用の文脈をコピー" aria-label="Permalink to &quot;LLM 用の文脈をコピー&quot;">​</a></h2><p><strong>このページの文脈をコピー</strong> / <strong>文脈をコピー</strong> は、現在のページ、選択中のコマ、ノート本文、タグ、出典からプロンプトを組み立てます。</p><ul><li>コピーダイアログには編集可能な <strong>テンプレート前置き</strong> があります。</li><li>使用できるプレースホルダー：<code>{volume}</code>、<code>{chapter}</code>、<code>{page}</code>、<code>{panel}</code>、<code>{notes}</code>、<code>{text}</code>、<code>{tags}</code>。</li><li>テンプレートの編集内容は自動で記憶されます。</li><li><strong>プレビュー</strong> はコピーされる内容をそのまま表示し、<strong>コピー</strong> でクリップボードに入れます。</li></ul><p>既定のテンプレートは、言語的なポイント、語気、文化的背景の説明と、誤解の指摘をモデルに求めます。好みの講師スタイルに一度合わせれば、以降のコピーはすべてそれに従います。</p><h2 id="一覧と検索" tabindex="-1">一覧と検索 <a class="header-anchor" href="#一覧と検索" aria-label="Permalink to &quot;一覧と検索&quot;">​</a></h2><p><strong>一覧 / 検索</strong> タブは、現在のページだけでなくライブラリ全体で動作します。</p><ul><li>ノート本文、タグ、出典のテキストを検索します。</li><li>巻、話、ページ番号、タグ、出典で絞り込みます。</li><li>結果を話、タグ、出典でまとめます。</li><li>結果のヘッダーには、何ページから何件のノートが見つかったかが表示されます。</li><li>結果をクリックするとそのページへ移動し、コマ単位のノートならそのコマへ移動します。</li></ul><p><strong>絞り込みを解除</strong> は現在のクエリをリセットします。</p><h2 id="一時メモ" tabindex="-1">一時メモ <a class="header-anchor" href="#一時メモ" aria-label="Permalink to &quot;一時メモ&quot;">​</a></h2><p>一時メモは、どこに属するか決まる前に浮かんだ考えを置いておく場所です——頭の中の余白です。</p><ol><li><strong>一時メモ</strong> に入力し、<code>Ctrl+Enter</code> または <strong>メモする</strong> を押します。</li><li>後で <strong>このページへ</strong> または <strong>このコマへ</strong> を使って、正式なノートとして整理します。</li></ol><h2 id="編集と削除" tabindex="-1">編集と削除 <a class="header-anchor" href="#編集と削除" aria-label="Permalink to &quot;編集と削除&quot;">​</a></h2><p>保存済みの各ノートには <strong>編集</strong>、<strong>文脈をコピー</strong>、<strong>タグで絞り込む</strong>、削除の操作があります。ノートの <strong>表示 / ソース</strong> 切り替えで、レンダリングされた Markdown と生のテキストを切り替えます。コマを削除すると、そのコマに紐付くノートも削除されるため、レイアウトに依存せず残したい内容はページノートを使ってください。</p><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>ノートが意図しない範囲に入った。</strong> エディター上の文を確認してください。コマ番号が示されているか、<em>ページ全体</em> と書かれています。ページノートを書きたいときはコマの選択を解除します。</li><li><strong><code>Ctrl+Enter</code> が効かなかった。</strong> フォーカスがノートエディター内にある必要があります。検索フィールドではショートカットは動作しません。</li><li><strong>貼り付けたスクリーンショットが大きすぎる。</strong> 上限を超える画像は自動で縮小されますが、ページ全体のスクリーンショットは依然として重いので、先に切り取ってください。</li><li><strong>タグの絞り込みでノートが隠れる。</strong> <strong>絞り込み</strong> の行はページ単位のもので、一覧の絞り込みとは別です。</li><li><strong>テキストがコードのように見える。</strong> コードブロックには、それぞれ独立した行に3つのバッククォートが必要です。</li></ul><figure class="shot"><div class="shot-missing"><strong>スクリーンショット未掲載：ツールバーと添付画像付きのノートエディター</strong> Markdown ツールバー、タグの行、画像のサムネイルを拡大したものを、ここに追加する予定です。 </div><figcaption>掲載予定：エディターのツールバー、タグ、添付画像。</figcaption></figure><h2 id="スクリーンショット未掲載" tabindex="-1">スクリーンショット未掲載 <a class="header-anchor" href="#スクリーンショット未掲載" aria-label="Permalink to &quot;スクリーンショット未掲載&quot;">​</a></h2><table tabindex="0"><thead><tr><th>図</th><th>必要な箇所</th></tr></thead><tbody><tr><td>一覧検索</td><td>絞り込み、まとめ、ページへの移動</td></tr><tr><td>文脈コピーダイアログ</td><td>テンプレート前置きとプレビュー</td></tr></tbody></table><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/compare">比較リーダー</a> — ほとんどのノートが生まれる場所。</li><li><a href="/KomaYomi-docs/ja/guide/export">エクスポート</a> — ノートが学習ドキュメントになるまで。</li><li><a href="/KomaYomi-docs/ja/guide/shortcuts">キーボードショートカット</a> — エディターと全体のキー。</li></ul>',44)])])}const f=a(i,[["render",n]]);export{b as __pageData,f as default};
